fn swap_first_and_last(a: &mut Vec<i32>) {
    // Since the problem guarantees the vector is non-empty,
    // it's safe to call `len()` and subtract 1.
    if a.len() >= 2 {
        a.swap(0, a.len() - 1);
    }
}

